package com.atlasiq.enterprise;
import jakarta.enterprise.context.ApplicationScoped;import java.nio.charset.StandardCharsets;import java.security.*;import java.sql.Timestamp;import java.time.Instant;import java.util.*;
@ApplicationScoped public class ApiCredentialService {private final EnterpriseStore store;public ApiCredentialService(EnterpriseStore s){store=s;}public IssuedKey issue(String org,String ws,String name,String role){String secret="atl_"+UUID.randomUUID().toString().replace("-","")+UUID.randomUUID().toString().replace("-","");String id=UUID.randomUUID().toString();store.exec("INSERT INTO atlasiq_api_key(id,organization_id,workspace_id,name,key_hash,role,created_at) VALUES(?,?,?,?,?,?,?)",id,org,ws,name,hash(secret),role,Timestamp.from(Instant.now()));return new IssuedKey(id,secret,name,role);}public String createServiceAccount(String org,String ws,String name,String role){String id=UUID.randomUUID().toString();store.exec("INSERT INTO atlasiq_service_account(id,organization_id,workspace_id,name,role,created_at) VALUES(?,?,?,?,?,?)",id,org,ws,name,role,Timestamp.from(Instant.now()));return id;}private String hash(String x){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(x.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}public record IssuedKey(String id,String secret,String name,String role){}}
